export type Cell = [x: number, y: number];

const key = ([x, y]: Cell): string => `${x},${y}`;

const neighborsOf = ([x, y]: Cell): Cell[] => {
  const neighbors: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) neighbors.push([x + dx, y + dy]);
    }
  }
  return neighbors;
};

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const living = new Set(liveCells.map(key));

  const liveNeighborCount = (cell: Cell): number =>
    neighborsOf(cell).filter((neighbor) => living.has(key(neighbor))).length;

  const candidates = new Map<string, Cell>();
  for (const cell of liveCells) {
    candidates.set(key(cell), cell);
    for (const neighbor of neighborsOf(cell)) {
      candidates.set(key(neighbor), neighbor);
    }
  }

  const survivors: Cell[] = [];
  for (const [cellKey, cell] of candidates) {
    const count = liveNeighborCount(cell);
    const isAlive = living.has(cellKey);
    if (count === 3 || (isAlive && count === 2)) survivors.push(cell);
  }
  return survivors;
}

